{
  "title": "The Mirror Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A map is unfurled at the ruined city's edge.",
      "visual_description": "Dusk over a broken skyline; a hand-drawn map spread on a stone, brass compass spinning, distant cracked spires behind.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The lamp wakes with a warning.",
      "visual_description": "An oil lamp on the stone, its single flame-eye flaring orange, throwing long shadows across the map.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "A clockwork scout is wound for the mission.",
      "visual_description": "Small tin fox standing on the map, key-wind tail turning, blue glass eyes catching lamplight.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The rescuer arrives through a cracked window.",
      "visual_description": "A figure in a clear diving helmet stepping out of a broken shop window as if surfacing from water, coat shimmering with city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They approach the looming castle gates.",
      "visual_description": "Massive iron gates hung with tattered royal banners; the four companions are tiny silhouettes against the rusted bars.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "A cursed tower tempts them off course.",
      "visual_description": "A leaning tower wrapped in violet smoke; the lamp's eye narrows in warning while Mara points firmly away.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The tin fox scouts an armored patrol.",
      "visual_description": "From behind a fallen column, the metal fox peers at distant plated figures marching with pikes through smoking rubble.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "They duck into a tax office for cover.",
      "visual_description": "Dim office full of toppled filing cabinets and floating receipts; a portly official snores at a desk, ledger as a pillow.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "Questions get only snores in reply.",
      "visual_description": "Mara shaking the official's shoulder; stamped papers stuck to his sleeves flutter, his mouth open in a deep snore.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Rumor of a winged beast above the rooftops.",
      "visual_description": "Through a shattered skylight, an enormous winged shadow sweeps across a blood-orange moon; the lamp's flame trembles.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Frightened faces peek from shuttered windows.",
      "visual_description": "Narrow alley lined with boarded windows; small frightened eyes glint through cracks as the tin fox trots past, leading the way.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The rescuer dives through a tall mirror.",
      "visual_description": "Glass diver plunging headfirst into a standing mirror in a ballroom, ripples spreading across the silvered surface like water.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Behind the mirror waits the captive.",
      "visual_description": "A dim mirror-world chamber where the sleeping tax collector is bound to a chair by enchanted red tape, still dozing peacefully.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "The lamp warns of a sealed magic door.",
      "visual_description": "An ornate door covered in glowing runes blocks the corridor; the oracle lamp hovers close, its eye casting symbols on the wood.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The fox's key-tail springs the lock.",
      "visual_description": "Tin fox inserting its wound tail into a keyhole; runes dim and the door cracks open in a wash of pale light.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "Reunion on the other side.",
      "visual_description": "Glass diver emerges from a wall mirror carrying the snoring official; Mara and the lamp wait in the doorway, relieved.",
      "characters": ["glass_diver", "sleeping_tax_collector", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "A patrol thunders behind them onto the bridge.",
      "visual_description": "Long stone bridge over a black chasm under tattered royal banners; the group races forward as armored shapes close behind in torchlight.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Across the bridge, the ruined city falls behind.",
      "visual_description": "Dawn breaking on the far bank; the companions silhouetted, the tin fox looking back as the broken skyline smolders behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

